        if '-' in v_no_build:
            parts = v_no_build.split('-', 1)
            version_part = parts[0]
            prerelease = parts[1]
        else:
            version_part = v_no_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            parsed_ids = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_ids.append((0, int(identifier)))  # numeric: (0, value)
                else:
                    parsed_ids.append((1, identifier))  # non-numeric: (1, string)
            prerelease_tuple = tuple(parsed_ids)
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def compare_key(v):
        version_nums, prerelease_tuple = parse_version(v)

        # For sorting:
        # 1. Compare MAJOR, MINOR, PATCH numerically
        # 2. A version with pre-release sorts before without pre-release
        #    (use False for with pre-release, True for without)
        # 3. Pre-release identifiers compared as parsed

        if prerelease_tuple is None:
            # No pre-release: sorts after any pre-release
            return (version_nums, (1,))
        else:
            # Has pre-release: sorts before any without pre-release
            # But we need to compare pre-releases properly
            return (version_nums, (0, prerelease_tuple))

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

